vec4 T(vec3 U) {
    if (iFrame%4==0) {
        U -= D(U).xyz;
        U -= LN(iChannel0,U).xyz;
        U -= LN(iChannel0,U).xyz;
        U -= LN(iChannel0,U).xyz;
    }
    return LN(iChannel0,U);
}
vec4 TB(vec3 U) {
    if (iFrame%4==0) {
        U -= D(U).xyz;
        U -= LN(iChannel0,U).xyz;
        U -= LN(iChannel0,U).xyz;
        U -= LN(iChannel0,U).xyz;
    }
    return LN(iChannel1,U);
}
